 "content": "from collections import Counter

def transform(grid):
    """Encode each 3x3 input block as its non-background marker color."""
    h, w = len(grid), len(grid[0])
    out = []
    for r in range(0, h, 3):
        row = []
        for c in range(0, w, 3):
            counts = Counter(
                grid[i][j]
                for i in range(r, min(r + 3, h))
                for j in range(c, min(c + 3, w))
                if grid[i][j] not in (0, 5)
            )
            row.append(counts.most_common(1)[0][0] if counts else 0)
        out.append(row)
    return out
